use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

// ----- Helpers -----

fn parent_of(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    node.borrow().parent_node.as_ref().and_then(|w| w.upgrade())
}

fn left_of(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    node.borrow().left_child_node.clone()
}

fn right_of(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    node.borrow().right_child_node.clone()
}

fn depth_of(node: &Rc<RefCell<BOSNode>>) -> u32 {
    node.borrow().depth
}

fn balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let n = node.borrow();
    let left_depth = n.left_child_node.as_ref().map_or(0, |l| l.borrow().depth as i32 + 1);
    let right_depth = n.right_child_node.as_ref().map_or(0, |r| r.borrow().depth as i32 + 1);
    right_depth - left_depth
}

fn recompute_depth(node: &Rc<RefCell<BOSNode>>) {
    let mut n = node.borrow_mut();
    let ld = n.left_child_node.as_ref().map_or(0, |l| l.borrow().depth + 1);
    let rd = n.right_child_node.as_ref().map_or(0, |r| r.borrow().depth + 1);
    n.depth = std::cmp::max(ld, rd);
}

fn parent_left_child_eq(parent: &Rc<RefCell<BOSNode>>, child: &Rc<RefCell<BOSNode>>) -> bool {
    parent.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, child))
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        match &self.root_node {
            Some(r) => {
                let r = r.borrow();
                r.left_child_count + r.right_child_count + 1
            }
            None => 0,
        }
    }

    fn rotate_right(&mut self, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        // L = P->left
        let l = p.borrow().left_child_node.clone().expect("rotate_right with no left child");
        let p_parent = parent_of(p);

        // Update parent's pointer to L
        match &p_parent {
            Some(pp) => {
                if parent_left_child_eq(pp, p) {
                    pp.borrow_mut().left_child_node = Some(l.clone());
                } else {
                    pp.borrow_mut().right_child_node = Some(l.clone());
                }
            }
            None => {
                self.root_node = Some(l.clone());
            }
        }

        // L->parent = P->parent
        l.borrow_mut().parent_node = p_parent.as_ref().map(|pp| Rc::downgrade(pp));

        // P->left = L->right
        let l_right = l.borrow().right_child_node.clone();
        let l_right_count = l.borrow().right_child_count;
        p.borrow_mut().left_child_node = l_right.clone();
        p.borrow_mut().left_child_count = l_right_count;
        if let Some(lr) = &l_right {
            lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }

        // recompute P depth
        recompute_depth(p);
        // P->parent = L
        p.borrow_mut().parent_node = Some(Rc::downgrade(&l));

        // L->right = P; L->right_count = P->left_count + P->right_count + 1
        let p_l_count = p.borrow().left_child_count;
        let p_r_count = p.borrow().right_child_count;
        l.borrow_mut().right_child_node = Some(p.clone());
        l.borrow_mut().right_child_count = p_l_count + p_r_count + 1;
        // recompute L depth
        recompute_depth(&l);

        l
    }

    fn rotate_left(&mut self, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
        let r = p.borrow().right_child_node.clone().expect("rotate_left with no right child");
        let p_parent = parent_of(p);

        match &p_parent {
            Some(pp) => {
                if parent_left_child_eq(pp, p) {
                    pp.borrow_mut().left_child_node = Some(r.clone());
                } else {
                    pp.borrow_mut().right_child_node = Some(r.clone());
                }
            }
            None => {
                self.root_node = Some(r.clone());
            }
        }

        r.borrow_mut().parent_node = p_parent.as_ref().map(|pp| Rc::downgrade(pp));

        let r_left = r.borrow().left_child_node.clone();
        let r_left_count = r.borrow().left_child_count;
        p.borrow_mut().right_child_node = r_left.clone();
        p.borrow_mut().right_child_count = r_left_count;
        if let Some(rl) = &r_left {
            rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
        }

        recompute_depth(p);
        p.borrow_mut().parent_node = Some(Rc::downgrade(&r));

        let p_l_count = p.borrow().left_child_count;
        let p_r_count = p.borrow().right_child_count;
        r.borrow_mut().left_child_node = Some(p.clone());
        r.borrow_mut().left_child_count = p_l_count + p_r_count + 1;
        recompute_depth(&r);

        r
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Find insert position
        let mut parent_opt: Option<Rc<RefCell<BOSNode>>> = None;
        let mut current = self.root_node.clone();
        let mut went_left = false;
        while let Some(curr) = current {
            parent_opt = Some(curr.clone());
            let cmp = (self.cmp_function)(&key, &curr.borrow().key);
            if cmp < 0 {
                curr.borrow_mut().left_child_count += 1;
                went_left = true;
                current = curr.borrow().left_child_node.clone();
            } else {
                curr.borrow_mut().right_child_count += 1;
                went_left = false;
                current = curr.borrow().right_child_node.clone();
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_opt.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        match &parent_opt {
            None => {
                self.root_node = Some(new_node.clone());
                return new_node;
            }
            Some(p) => {
                if went_left {
                    p.borrow_mut().left_child_node = Some(new_node.clone());
                } else {
                    p.borrow_mut().right_child_node = Some(new_node.clone());
                }
            }
        }

        // Now bubble up if depth changed
        let parent = parent_opt.unwrap();
        let has_left = parent.borrow().left_child_node.is_some();
        let has_right = parent.borrow().right_child_node.is_some();
        if has_left ^ has_right {
            parent.borrow_mut().depth += 1;
            let mut pn_opt = parent_of(&parent);
            while let Some(pn) = pn_opt {
                let new_left_depth = pn.borrow().left_child_node.as_ref().map_or(0, |l| l.borrow().depth + 1);
                let new_right_depth = pn.borrow().right_child_node.as_ref().map_or(0, |r| r.borrow().depth + 1);
                let max_depth = std::cmp::max(new_left_depth, new_right_depth);
                if pn.borrow().depth != max_depth {
                    pn.borrow_mut().depth = max_depth;
                } else {
                    break;
                }

                // Check AVL property
                let mut new_pn = pn.clone();
                if new_left_depth >= 2 && new_left_depth - 2 == new_right_depth {
                    // left-right case
                    let l = pn.borrow().left_child_node.clone().unwrap();
                    if balance(&l) > 0 {
                        self.rotate_left(&l);
                    }
                    new_pn = self.rotate_right(&pn);
                } else if new_right_depth >= 2 && new_left_depth + 2 == new_right_depth {
                    let r = pn.borrow().right_child_node.clone().unwrap();
