    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let (count_after, valid) = {
            let mut n = node.borrow_mut();
            if n.weak_ref_count > 0 {
                n.weak_ref_count -= 1;
            }
            (n.weak_ref_count, n.weak_ref_node_valid)
        };
        if count_after == 0 {
            if let Some(ff) = self.free_function {
                ff(node);
            }
            None
        } else if valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(c) = current {
            let cmp = (self.cmp_function)(key, &c.borrow().key);
            if cmp == 0 {
                return Some(c);
            } else if cmp < 0 {
                current = c.borrow().left_child_node.clone();
            } else {
                current = c.borrow().right_child_node.clone();
            }
        }
        None
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        while let Some(c) = current {
            let lcc = c.borrow().left_child_count;
            if lcc <= idx {
                idx -= lcc;
                if idx == 0 {
                    return Some(c);
                }
                idx -= 1;
                current = c.borrow().right_child_node.clone();
            } else {
                current = c.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        // No-op print
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    {
        let mut n = node.borrow_mut();
        n.weak_ref_count += 1;
    }
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(r) = node.borrow().right_child_node.clone() {
        let mut current = r;
        loop {
            let l = current.borrow().left_child_node.clone();
            match l {
                Some(ll) => current = ll,
                None => return Some(current),
            }
        }
    } else {
        let mut current = node.clone();
        loop {
            let parent = parent_of(&current);
            match parent {
                Some(p) => {
                    let is_right = p.borrow().right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &current));
                    if is_right {
                        current = p;
                    } else {
                        return Some(p);
                    }
                }
                None => return None,
            }
        }
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(l) = node.borrow().left_child_node.clone() {
        let mut current = l;
        loop {
            let r = current.borrow().right_child_node.clone();
            match r {
                Some(rr) => current = rr,
                None => return Some(current),
            }
        }
    } else {
        let mut current = node.clone();
        loop {
            let parent = parent_of(&current);
            match parent {
                Some(p) => {
                    let is_left = p.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &current));
                    if is_left {
                        current = p;
                    } else {
                        return Some(p);
                    }
                }
                None => return None,
            }
        }
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    loop {
        let parent = parent_of(&current);
        match parent {
            Some(p) => {
                let is_right = p.borrow().right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &current));
                if is_right {
                    counter += 1 + p.borrow().left_child_count;
                }
                current = p;
            }
            None => return counter,
        }
    }
}
